  CIV.greenhouse = function (I, gx, gy) { const b = I.box(gx, gy, 2, 1.2, 14, '#bfe3ef', 0, { tex: 'glass', top: 0.05 }); [0.2, 0.5, 0.8].forEach(u => { const q = I.p(gx + u * 2, gy + 0.6, 4); I.blob(q[0], q[1], 4, '#5cc464', 0.7); }); I.roof(gx, gy, 2, 1.2, 14, 9, '#d6eef5', 0.04); I.line(I.up(b.D, 7), I.up(b.C, 7), 'rgba(255,255,255,.7)', 1); I.label(gx + 1, gy + 1.7, 'Greenhouse', '', 8); };
  CIV.verticalfarm = function (I, gx, gy, now) { const H = 120, b = I.box(gx, gy, 2, 2, H, '#cfe9f2', 0, { tex: 'glass', top: 0.08 }); for (let v = 10; v < H; v += 18) { I.line(I.up(b.D, v), I.up(b.C, v), '#3fa66b', 3); I.line(I.up(b.C, v), I.up(b.B, v), '#2f8f5b', 3); } I.flatRoof(gx, gy, 2, 2, H, '#dfe5ee'); const q = I.p(gx + 1, gy + 1, H + 4); I.blob(q[0], q[1], 8, '#5cc464', 0.7); I.lights.push({ x: q[0], y: q[1] + 40, r: 40, c: '160,255,190', k: 0.5 }); void now; I.label(gx + 1, gy + 2.6, 'Vertical farm', 'food, floor on floor', 8); };
