  CIV.waterworks = function (I, gx, gy) { I.box(gx, gy, 2, 2, 3, '#c9d2dc', 0, { top: 0.1 }); [[0.55, 0.55], [1.45, 0.55]].forEach(o => { const r = cyl(I, gx + o[0], gy + o[1], 0.38, 3, 14, '#9fc4e0'); I.ctx.fillStyle = '#4b8fb0'; I.ctx.beginPath(); I.ctx.ellipse(r.top[0], r.top[1], r.rx * 0.8, r.ry * 0.8, 0, 0, Math.PI * 2); I.ctx.fill(); }); I.box(gx + 0.2, gy + 1.2, 1.6, 0.6, 16, '#e9e2d0', 3, { noShadow: true, tex: 'siding' }); I.label(gx + 1, gy + 2.6, 'Water works', 'clean water for every tap', 8); };
