  CIV.windturbine = function (I, gx, gy, now) { const b = I.p(gx + 0.5, gy + 0.5); I.ctx.fillStyle = 'rgba(20,40,30,.2)'; I.ctx.beginPath(); I.ctx.ellipse(b[0] + 2, b[1] + 1, 6, 3, 0, 0, Math.PI * 2); I.ctx.fill(); I.poly([[b[0] - 3, b[1]], [b[0] + 3, b[1]], [b[0] + 1.2, b[1] - 64], [b[0] - 1.2, b[1] - 64]], '#e6e9ef'); const c = [b[0], b[1] - 66], a0 = reduce ? 0.5 : now / 700; I.ctx.strokeStyle = '#f4f7fa'; I.ctx.lineWidth = 2.5; for (let i = 0; i < 3; i++) { const a = a0 + i * Math.PI * 2 / 3; I.ctx.beginPath(); I.ctx.moveTo(c[0], c[1]); I.ctx.lineTo(c[0] + Math.cos(a) * 22, c[1] + Math.sin(a) * 12); I.ctx.stroke(); } I.blob(c[0], c[1], 2.5, '#c9d2dc'); };
