  CIV.fusion = function (I, gx, gy, now) { I.box(gx, gy, 2, 2, 5, '#c9d2dc', 0, { top: 0.1 }); const c = I.p(gx + 1, gy + 1, 5); const g = I.ctx.createRadialGradient(c[0] - 10, c[1] - 22, 3, c[0], c[1] - 6, 40); g.addColorStop(0, '#ffffff'); g.addColorStop(1, '#9aa3b0'); I.ctx.fillStyle = g; I.ctx.beginPath(); I.ctx.ellipse(c[0], c[1], 36, 30, 0, Math.PI, 0); I.ctx.closePath(); I.ctx.fill(); const k = 0.6 + Math.sin(now / 400) * 0.2; I.ctx.strokeStyle = 'rgba(79,240,255,' + k + ')'; I.ctx.lineWidth = 3; I.ctx.beginPath(); I.ctx.ellipse(c[0], c[1] - 8, 30, 12, 0, 0, Math.PI * 2); I.ctx.stroke(); I.lights.push({ x: c[0], y: c[1] - 6, r: 60, c: '120,220,255', k: 0.8 }); I.label(gx + 1, gy + 2.6, 'Fusion core', 'power without end', 8); };
