  B.boulder = function (I, gx, gy, size) { size = size || 1; const b = I.p(gx + 0.5, gy + 0.55); I.ctx.fillStyle = 'rgba(20,30,30,.22)'; I.ctx.beginPath(); I.ctx.ellipse(b[0] + 3, b[1] + 1, 9 * size, 4 * size, 0, 0, Math.PI * 2); I.ctx.fill(); I.ctx.fillStyle = '#8c8a85'; I.ctx.beginPath(); I.ctx.moveTo(b[0] - 8 * size, b[1]); I.ctx.quadraticCurveTo(b[0] - 7 * size, b[1] - 9 * size, b[0] - 1 * size, b[1] - 9 * size); I.ctx.quadraticCurveTo(b[0] + 8 * size, b[1] - 8 * size, b[0] + 8 * size, b[1]); I.ctx.closePath(); I.ctx.fill(); I.ctx.fillStyle = '#a3a19b'; I.ctx.beginPath(); I.ctx.moveTo(b[0] - 6 * size, b[1] - 2); I.ctx.quadraticCurveTo(b[0] - 5 * size, b[1] - 8 * size, b[0], b[1] - 8 * size); I.ctx.lineTo(b[0], b[1] - 1); I.ctx.closePath(); I.ctx.fill(); };
