  B.cactus = function (I, gx, gy, size) { size = size || 1; const b = I.p(gx + 0.5, gy + 0.5); I.ctx.fillStyle = 'rgba(20,40,30,.2)'; I.ctx.beginPath(); I.ctx.ellipse(b[0] + 3, b[1] + 1, 6 * size, 2.5 * size, 0, 0, Math.PI * 2); I.ctx.fill(); I.roundRect(b[0] - 3 * size, b[1] - 26 * size, 6 * size, 26 * size, 3 * size, '#3f8f4a'); I.roundRect(b[0] - 10 * size, b[1] - 20 * size, 5 * size, 10 * size, 2.5 * size, '#3f8f4a'); I.roundRect(b[0] - 10 * size, b[1] - 20 * size, 8 * size, 4 * size, 2 * size, '#3f8f4a'); I.roundRect(b[0] + 5 * size, b[1] - 16 * size, 5 * size, 8 * size, 2.5 * size, '#3f8f4a'); I.roundRect(b[0] + 2 * size, b[1] - 16 * size, 8 * size, 4 * size, 2 * size, '#3f8f4a'); I.ctx.strokeStyle = 'rgba(255,255,255,.35)'; I.ctx.lineWidth = 0.8; for (let v = 4; v < 24; v += 4) I.line([b[0] - 1, b[1] - v * size], [b[0] + 1, b[1] - v * size], 'rgba(0,0,0,.2)', 0.8); };
