  B.palm = function (I, gx, gy, size) { size = size || 1; const b = I.p(gx + 0.5, gy + 0.5); I.ctx.fillStyle = 'rgba(20,40,30,.22)'; I.ctx.beginPath(); I.ctx.ellipse(b[0] + 6, b[1] + 2, 12 * size, 4 * size, 0, 0, Math.PI * 2); I.ctx.fill(); I.ctx.strokeStyle = '#8a6a3f'; I.ctx.lineWidth = 3.5 * size; I.ctx.beginPath(); I.ctx.moveTo(b[0], b[1]); I.ctx.quadraticCurveTo(b[0] + 4 * size, b[1] - 18 * size, b[0] + 2 * size, b[1] - 34 * size); I.ctx.stroke(); for (let i = 0; i < 6; i++) { const a = i / 6 * Math.PI * 2; I.ctx.strokeStyle = i % 2 ? '#3fa66b' : '#5cc464'; I.ctx.lineWidth = 2.5 * size; I.ctx.beginPath(); I.ctx.moveTo(b[0] + 2 * size, b[1] - 34 * size); I.ctx.quadraticCurveTo(b[0] + 2 * size + Math.cos(a) * 12 * size, b[1] - 40 * size + Math.sin(a) * 4 * size, b[0] + 2 * size + Math.cos(a) * 16 * size, b[1] - 30 * size + Math.abs(Math.sin(a)) * 6 * size); I.ctx.stroke(); } I.blob(b[0] + 2 * size, b[1] - 33 * size, 2 * size, '#8a5a3a'); };
  CIV.foodcache = function (I, gx, gy) { /* a raised cache: food up off the ground, out of reach */ const b = I.p(gx + 0.5, gy + 0.5); I.ctx.fillStyle = 'rgba(20,40,30,.2)'; I.ctx.beginPath(); I.ctx.ellipse(b[0], b[1] + 1, 7, 3, 0, 0, Math.PI * 2); I.ctx.fill(); [[-5, 0], [5, 0]].forEach(o => { I.ctx.fillStyle = '#6b4a2b'; I.ctx.fillRect(b[0] + o[0] - 1, b[1] - 16, 2, 16); }); I.box(gx + 0.25, gy + 0.3, 0.5, 0.4, 9, '#c9a06a', 16, { noShadow: true, tex: 'siding' }); I.roof(gx + 0.25, gy + 0.3, 0.5, 0.4, 25, 6, '#8a5a3a', 0.08); const l = I.p(gx + 0.85, gy + 0.9); I.ctx.strokeStyle = '#8a5a3a'; I.ctx.lineWidth = 1.5; I.ctx.beginPath(); I.ctx.moveTo(l[0], l[1]); I.ctx.lineTo(l[0] - 6, l[1] - 15); I.ctx.stroke(); for (let i = 1; i < 5; i++) I.line([l[0] - i * 1.2 - 2, l[1] - i * 3], [l[0] - i * 1.2 + 2, l[1] - i * 3], '#8a5a3a', 1.2); };
